    V13119_HESSIAN_CORRECTION_ERRORS[('plus',z)]=float(np.max(abs(np.sort(ep)-_v13119_plus_target(z))))
    V13119_HESSIAN_CORRECTION_ERRORS[('minus',z)]=float(np.max(abs(np.sort(em)-_v13119_minus_target(z))))
