def _v13120_cluster(vals,tol=1e-7):
    out=[]
    for v in np.sort(np.asarray(vals,float)):
        if not out or abs(v-out[-1][0])>tol:
            out.append([float(v),1])
        else:
            x,m=out[-1]
            out[-1][0]=(x*m+float(v))/(m+1)
            out[-1][1]=m+1
    return [(x,m) for x,m in out]

