def _v13129_hessian_cart(which,h=1e-4):
    x=np.zeros(12);H=np.zeros((12,12))
    f0=_v13129_cart_actions(x)[which]
    for i in range(12):
        ei=np.zeros(12);ei[i]=h
        H[i,i]=(_v13129_cart_actions(ei)[which]-2*f0+_v13129_cart_actions(-ei)[which])/h**2
        for j in range(i+1,12):
            ej=np.zeros(12);ej[j]=h
            H[i,j]=H[j,i]=(
                _v13129_cart_actions(ei+ej)[which]
                -_v13129_cart_actions(ei-ej)[which]
                -_v13129_cart_actions(-ei+ej)[which]
                +_v13129_cart_actions(-ei-ej)[which]
            )/(4*h*h)
    return H

