# v13.224 — GENERAL SU(n+1)/U(n) CONSTRUCTION FOR n=3,2,1
# ================================================================================================
# Build normalized Hermitian generators for the three recursive levels.
# P selects the first coordinate.  The fixed-distinction algebra h is u(n), and m consists of the
# 2n off-diagonal real/imaginary directions connecting the distinguished line to its complement.

def _v13224_pair(n):
    N=n+1
    h=[]
    # su(n) on the complement
    for i in range(n):
        for j in range(i+1,n):
            X=np.zeros((N,N),complex); X[i+1,j+1]=X[j+1,i+1]=1
            Y=np.zeros((N,N),complex); Y[i+1,j+1]=-1j; Y[j+1,i+1]=1j
            h.extend([X,Y])
    for k in range(1,n):
        vals=np.zeros(N)
        vals[1:1+k]=1
        vals[1+k]=-k
        vals*=math.sqrt(2/(k*(k+1)))
        h.append(np.diag(vals).astype(complex))
    qvals=np.array([n]+[-1]*n,float)*math.sqrt(2/(n*(n+1)))
    Q=np.diag(qvals).astype(complex)
    h.append(Q)

    m=[]
    for j in range(1,N):
        X=np.zeros((N,N),complex); X[0,j]=X[j,0]=1
        Y=np.zeros((N,N),complex); Y[0,j]=-1j; Y[j,0]=1j
        m.extend([X,Y])
    return h,m,Q

def _v13224_lie(A,B):
    return (A@B-B@A)/1j

def _v13224_coeff(X,basis):
    return np.array([float(np.real(np.trace(B@X)/2)) for B in basis])

