# unique.  Thus the current no-extra-distinction rule removes the old anisotropic weighting.

# Verify the formula numerically on several coefficient triples.
def _v13309_D(coeff):
    return sum(float(coeff[k])*np.kron(V13308_J[k],V13308_AH[k]) for k in range(3))

def _v13309_radial_tensor(coeff):
    # Reconstruct the quadratic form n -> Tr_int[(R D T)(R D T)^T] by axis samples and polarization.
    D=_v13309_D(coeff)
    def q(n):
        n=np.asarray(n,float); n=n/np.linalg.norm(n)
        R=np.outer(n,n); T=np.eye(3)-R
        B=np.kron(R,np.eye(8))@D@np.kron(T,np.eye(8))
        BB=B@B.T
        # partial trace over internal 8 -> external 3x3
        M=np.zeros((3,3))
        for a in range(3):
            for b in range(3):
                M[a,b]=np.trace(BB[8*a:8*(a+1),8*b:8*(b+1)])
        return float(n@M@n)
